#include <vector>

class Solution {
public:
    std::vector<std::vector<int>> splitByPrimes(std::vector<int>& nums) {
        int n = nums.size();
        if (n == 0) return {};

        std::vector<bool> is_prime(n, true);
        if (n > 0) is_prime[0] = false;
        if (n > 1) is_prime[1] = false;
        for (int i = 2; i * i < n; ++i) {
            if (is_prime[i]) {
                for (int j = i * i; j < n; j += i) is_prime[j] = false;
            }
        }

        std::vector<std::vector<int>> res;
        std::vector<int> curr;
        for (int i = 0; i < n; ++i) {
            if (is_prime[i]) {
                if (!curr.empty()) res.push_back(curr);
                curr = {nums[i]};
            } else {
                curr.push_back(nums[i]);
            }
        }
        if (!curr.empty()) res.push_back(curr);
        return res;
    }
};

import java.util.*;

class Solution {
    public List<List<Integer>> splitByPrimes(int[] nums) {
        int n = nums.length;
        if (n == 0) return new ArrayList<>();

        boolean[] isPrime = new boolean[n];
        Arrays.fill(isPrime, true);
        if (n > 0) isPrime[0] = false;
        if (n > 1) isPrime[1] = false;
        for (int i = 2; i * i < n; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j < n; j += i) isPrime[j] = false;
            }
        }

        List<List<Integer>> res = new ArrayList<>();
        List<Integer> curr = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (isPrime[i]) {
                if (!curr.isEmpty()) res.add(curr);
                curr = new ArrayList<>();
                curr.add(nums[i]);
            } else {
                curr.add(nums[i]);
            }
        }
        if (!curr.isEmpty()) res.add(curr);
        return res;
    }
}

