var splitByPrimes = function(nums) {
    const n = nums.length;
    if (n === 0) return [];

    const isPrime = new Uint8Array(n).fill(1);
    if (n > 0) isPrime[0] = 0;
    if (n > 1) isPrime[1] = 0;
    for (let i = 2; i * i < n; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j < n; j += i) isPrime[j] = 0;
        }
    }

    const res = [];
    let curr = [];
    for (let i = 0; i < n; i++) {
        if (isPrime[i]) {
            if (curr.length > 0) res.push(curr);
            curr = [nums[i]];
        } else {
            curr.push(nums[i]);
        }
    }
    if (curr.length > 0) res.push(curr);
    return res;
};
